import math

def check_good_function(n, k, max_val=5):
    """
    Checks if g(x) = x^k is an n-good function for integers a, b in [-max_val, max_val].
    """
    is_good = True

    # Iterate over distinct pairs (a, b)
    for a in range(-max_val, max_val + 1):
        for b in range(-max_val, max_val + 1):
            if a == b:
                continue

            try:
                # Calculate g(a) and g(b)
                g_a = a**k
                g_b = b**k

                divisor = g_a - g_b
                dividend = a**n - b**n

                if divisor == 0:
                    # Divisibility holds only if dividend is also 0
                    if dividend != 0:
                        is_good = False
                        print(f"Failed check for n={n}, k={k}: a={a}, b={b}. Divisor=0, Dividend={dividend} != 0.")
                        return False
                    # If both are 0, it holds.
                    continue

                # Check if divisor divides dividend
                if dividend % divisor != 0:
                    is_good = False
                    print(f"Failed check for n={n}, k={k}: a={a}, b={b}. Divisor={divisor}, Dividend={dividend}. {dividend} % {divisor} != 0.")
                    return False
            except OverflowError:
                print(f"Overflow occurred for n={n}, k={k} with a={a}, b={b}. Skipping pair.")
                # This shouldn't happen for small max_val, but good practice.
                continue

    return is_good

def find_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

print("--- Verification Results (n=1 to n=5) ---")
results = {}

for n in range(1, 6):
    divisors = find_divisors(n)
    good_k_list = []
    print(f"\nTesting n = {n}. Potential exponents k: {divisors}")

    for k in divisors:
        is_n_good = check_good_function(n, k)
        if is_n_good:
            good_k_list.append(k)

    results[n] = good_k_list
    print(f"Found {len(good_k_list)} n-good functions assuming g(x)=x^k: k in {good_k_list}")

print("\nSummary of C(n) based on g(x)=x^k assumption:")
for n, k_list in results.items():
    print(f"C({n}) = {len(k_list)}. Functions: {{x^{k} | k in {k_list}}}")

def count_divisors(n):
    count = 0
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            if i * i == n:
                count += 1
            else:
                count += 2
    return count

def is_exotic(n, d_n):
    # n is exotic if d(n) = 2 * (odd integer)
    if d_n % 2 != 0:
        # d(n) must be even
        return False

    m = d_n // 2
    return m % 2 != 0

print("n | d(n) | Exotic (d(n) = 2 * odd)")
print("-" * 40)

exotic_list = []
for n in range(1, 51):
    d_n = count_divisors(n)
    exotic = is_exotic(n, d_n)

    print(f"{n:2} | {d_n:4} | {str(exotic)}")

    if exotic:
        exotic_list.append(n)

print("\nList of exotic integers up to 50:", exotic_list)
